"use client";

import * as React from "react";
import { ChevronDown } from "lucide-react";
import { TextMorph } from "./text-morph";
import {
  INTERACTION_FOCUS,
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

export interface SplitMenuItem {
  id: string;
  label: string;
  icon?: React.ReactNode;
  onSelect: () => void;
  destructive?: boolean;
  disabled?: boolean;
}

export interface SplitButtonProps {
  label: string;
  icon?: React.ReactNode;
  onClick?: () => void;
  menuItems: SplitMenuItem[];
  variant?: "primary" | "secondary" | "destructive";
  size?: "sm" | "md" | "lg";
  disabled?: boolean;
  loading?: boolean;
  menuLabel?: string;
  className?: string;
}

// Exact physics & timing from FilterBar
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const UI = "cubic-bezier(0.23,1,0.32,1)";
const OPEN = 280;
const CLOSE = 200;
const ROW_H = 32;

type Phase = "closed" | "opening" | "open" | "closing";
type Box = { left: number; top: number; width: number; height: number };

const variantStyles = {
  primary: {
    container: "bg-primary text-primary-foreground",
    action:
      "hover:bg-primary-foreground/10 active:bg-primary-foreground/15 text-primary-foreground",
    trigger:
      "hover:bg-primary-foreground/10 active:bg-primary-foreground/15 text-primary-foreground",
    divider: "bg-primary-foreground/25",
  },
  secondary: {
    container: "bg-card text-foreground shadow-[inset_0_0_0_1px_var(--border)]",
    action: "hover:bg-accent active:bg-accent/80 text-foreground",
    trigger: "hover:bg-accent active:bg-accent/80 text-foreground",
    divider: "bg-border",
  },
  destructive: {
    container:
      "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400",
    action:
      "hover:bg-red-500/15 active:bg-red-500/20 text-red-600 dark:text-red-400",
    trigger:
      "hover:bg-red-500/15 active:bg-red-500/20 text-red-600 dark:text-red-400",
    divider: "bg-red-500/25",
  },
};

const sizeStyles = {
  sm: {
    height: "h-7 text-[12px] rounded-full",
    actionPad: "pl-3 pr-2 gap-1.5",
    triggerPad: "px-2",
    iconSize: 13,
  },
  md: {
    height: "h-9 text-[13px] rounded-full",
    actionPad: "pl-4 pr-2.5 gap-2",
    triggerPad: "px-2.5",
    iconSize: 14,
  },
  lg: {
    height: "h-10 text-[14px] rounded-full",
    actionPad: "pl-5 pr-3 gap-2.5",
    triggerPad: "px-3",
    iconSize: 16,
  },
};

export function SplitButton({
  label,
  icon,
  onClick,
  menuItems,
  variant = "primary",
  size = "md",
  disabled = false,
  loading = false,
  menuLabel = "More actions",
  className = "",
}: SplitButtonProps) {
  const reduced = useInteractionReducedMotion();
  const [phase, setPhase] = React.useState<Phase>("closed");
  const [box, setBox] = React.useState<Box>({
    left: 0,
    top: 0,
    width: 0,
    height: 36,
  });
  const [wrapW, setWrapW] = React.useState(200);
  const [panelH, setPanelH] = React.useState(0);
  const [activeIndex, setActiveIndex] = React.useState(0);

  const wrapRef = React.useRef<HTMLDivElement | null>(null);
  const triggerRef = React.useRef<HTMLButtonElement | null>(null);
  const panelRef = React.useRef<HTMLDivElement | null>(null);
  const timer = React.useRef<number>(0);

  const v = variantStyles[variant];
  const s = sizeStyles[size];
  const inert = disabled || loading;
  const mounted = phase !== "closed";
  const expanded = phase === "open";

  // Open the morphing floating dropdown from the trigger pill
  const openMenu = () => {
    const wrap = wrapRef.current;
    const trigger = triggerRef.current;
    if (!wrap || !trigger) return;
    window.clearTimeout(timer.current);
    const a = trigger.getBoundingClientRect();
    const w = wrap.getBoundingClientRect();
    setBox({
      left: a.left - w.left,
      top: a.top - w.top,
      width: a.width,
      height: a.height,
    });
    setWrapW(w.width);
    setActiveIndex(0);
    setPhase(reduced ? "open" : "opening");
  };

  const closeMenu = React.useCallback(
    (refocus = true) => {
      window.clearTimeout(timer.current);
      if (refocus) {
        triggerRef.current?.focus({ preventScroll: true });
      }
      if (reduced) {
        setPhase("closed");
        return;
      }
      setPhase("closing");
      timer.current = window.setTimeout(() => {
        setPhase("closed");
      }, CLOSE);
    },
    [reduced],
  );

  // FilterBar double-rAF expansion
  React.useEffect(() => {
    if (phase !== "opening") return;
    let inner = 0;
    const outer = requestAnimationFrame(() => {
      inner = requestAnimationFrame(() => setPhase("open"));
    });
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [phase]);

  // Clean timer on unmount
  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  // Measure content height dynamically
  React.useLayoutEffect(() => {
    const panel = panelRef.current;
    if (!panel) return;
    const measure = () => setPanelH(panel.offsetHeight);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(panel);
    return () => observer.disconnect();
  }, [menuItems, mounted]);

  // Close on outside pointer click
  React.useEffect(() => {
    if (!mounted || phase === "closing") return;
    const onPointerDown = (e: PointerEvent) => {
      if (!wrapRef.current?.contains(e.target as Node)) {
        closeMenu(false);
      }
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [mounted, phase, closeMenu]);

  // Keyboard navigation
  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (!mounted || phase === "closing") {
      if (
        e.key === "ArrowDown" &&
        document.activeElement === triggerRef.current
      ) {
        e.preventDefault();
        openMenu();
      }
      return;
    }

    if (e.key === "Escape") {
      e.preventDefault();
      closeMenu(true);
    } else if (e.key === "ArrowDown") {
      e.preventDefault();
      setActiveIndex((prev) => (prev < menuItems.length - 1 ? prev + 1 : 0));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setActiveIndex((prev) => (prev > 0 ? prev - 1 : menuItems.length - 1));
    } else if (e.key === "Home") {
      e.preventDefault();
      setActiveIndex(0);
    } else if (e.key === "End") {
      e.preventDefault();
      setActiveIndex(menuItems.length - 1);
    } else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      const current = menuItems[activeIndex];
      if (current && !current.disabled) {
        closeMenu(true);
        current.onSelect();
      }
    }
  };

  const handleActionClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (inert) {
      e.preventDefault();
      return;
    }
    onClick?.();
  };

  const toggleDropdown = (e: React.MouseEvent<HTMLButtonElement>) => {
    e.stopPropagation();
    if (inert) return;
    if (mounted && phase !== "closing") {
      closeMenu();
    } else {
      openMenu();
    }
  };

  // Dimensions & alignment: matches FilterBar's floating panel geometry
  const PANEL_W = 184;
  const menuWidth = Math.min(PANEL_W, Math.max(160, wrapW));
  const targetLeft = Math.max(0, box.left + box.width - menuWidth);
  const targetTop = box.top + box.height + 6;

  return (
    <div
      ref={wrapRef}
      onKeyDown={handleKeyDown}
      className={`relative isolate inline-flex select-none items-stretch transition-[scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] has-[button:active:not(:disabled)]:scale-[0.98] motion-reduce:transition-none motion-reduce:has-[button:active]:scale-100 ${s.height} ${v.container} ${
        disabled ? "opacity-45" : ""
      } ${className}`}
    >
      {/* Primary Action Button */}
      <button
        type="button"
        disabled={inert}
        onClick={handleActionClick}
        aria-busy={loading || undefined}
        className={`relative inline-flex items-center justify-center whitespace-nowrap rounded-l-full font-medium transition-colors duration-200 cursor-pointer disabled:cursor-default ${s.actionPad} ${v.action} ${INTERACTION_FOCUS}`}
      >
        {/* The slot opens for an icon or the spinner; they trade places through a blur. */}
        <span
          aria-hidden="true"
          className="relative flex shrink-0 items-center justify-center"
          style={{
            width: icon || loading ? s.iconSize : 0,
            height: s.iconSize,
            marginRight: icon || loading ? 6 : 0,
            transition: reduced
              ? "none"
              : `width 380ms ${EASE}, margin-right 380ms ${EASE}`,
          }}
        >
          <span
            className="absolute inset-0 flex items-center justify-center"
            style={interactionIcon(!loading, reduced)}
          >
            {icon}
          </span>
          <span
            className="absolute inset-0 flex items-center justify-center"
            style={interactionIcon(loading, reduced)}
          >
            <span
              className={`size-3 rounded-full border-[1.5px] border-current border-t-transparent ${loading ? "animate-spin" : ""}`}
            />
          </span>
        </span>
        <TextMorph>{label}</TextMorph>
      </button>

      {/* Quiet thin line Divider */}
      <span
        aria-hidden="true"
        className={`w-px my-1.5 self-stretch ${v.divider}`}
      />

      {/* Dropdown Chevron Trigger Button */}
      <button
        ref={triggerRef}
        type="button"
        disabled={inert}
        onClick={toggleDropdown}
        aria-label={menuLabel}
        aria-haspopup="menu"
        aria-expanded={mounted && phase !== "closing"}
        className={`relative inline-flex items-center justify-center rounded-r-full transition-colors duration-200 cursor-pointer disabled:cursor-default ${s.triggerPad} ${v.trigger} ${INTERACTION_FOCUS}`}
      >
        <ChevronDown
          size={s.iconSize}
          strokeWidth={1.75}
          style={{
            transform:
              mounted && phase !== "closing" ? "rotate(180deg)" : "none",
            transition: reduced ? "none" : `transform 300ms ${EASE}`,
          }}
        />
      </button>

      {/* Floating Panel: Morphs out from under the trigger pill with spring physics */}
      {mounted && (
        <div
          role="menu"
          aria-label={menuLabel}
          className="absolute z-50 overflow-hidden bg-popover text-popover-foreground"
          style={{
            top: targetTop,
            left: expanded ? targetLeft : box.left,
            width: expanded ? menuWidth : box.width,
            height: expanded ? panelH : box.height,
            borderRadius: expanded ? 12 : box.height / 2,
            opacity: expanded ? 1 : 0,
            boxShadow: "0 0 0 1px var(--border)",
            transition: reduced
              ? "none"
              : phase === "closing"
                ? `width ${CLOSE}ms ${UI}, height ${CLOSE}ms ${UI}, left ${CLOSE}ms ${UI}, border-radius ${CLOSE}ms ${UI}, opacity ${CLOSE}ms ${UI}`
                : `width ${OPEN}ms ${UI}, height ${OPEN}ms ${UI}, left ${OPEN}ms ${UI}, border-radius ${OPEN}ms ${UI}, opacity 160ms ${UI}`,
          }}
        >
          <div
            ref={panelRef}
            inert={!expanded ? true : undefined}
            className="relative p-1"
            style={{
              width: menuWidth,
              opacity: expanded ? 1 : 0,
              transition: reduced
                ? "none"
                : expanded
                  ? `opacity 180ms ${EASE} 60ms`
                  : "opacity 90ms ease-out",
            }}
          >
            {/* The Internal Highlight Glides Between Menu Rows */}
            <span
              aria-hidden="true"
              className="pointer-events-none absolute inset-x-1 top-1 h-8 rounded-[7px] bg-accent"
              style={{
                transform: `translateY(${activeIndex * ROW_H}px)`,
                opacity: activeIndex >= 0 && menuItems.length > 0 ? 1 : 0,
                transition: reduced ? "none" : `transform 160ms ${UI}`,
              }}
            />

            {/* Menu Items */}
            {menuItems.map((item, index) => {
              const isDestructive = item.destructive;
              const isSelected = activeIndex === index;

              return (
                <button
                  key={item.id}
                  type="button"
                  role="menuitem"
                  data-menu-item=""
                  disabled={item.disabled}
                  onPointerEnter={() => !item.disabled && setActiveIndex(index)}
                  onClick={() => {
                    closeMenu(false);
                    item.onSelect();
                  }}
                  className={`relative z-10 flex h-8 w-full items-center gap-2 rounded-[7px] px-2.5 text-[13px] font-medium transition-colors cursor-pointer disabled:cursor-not-allowed disabled:opacity-40 select-none text-left ${
                    isDestructive
                      ? isSelected
                        ? "text-red-600 dark:text-red-400 font-semibold"
                        : "text-red-500/90 dark:text-red-400/90"
                      : isSelected
                        ? "text-foreground font-semibold"
                        : "text-muted-foreground"
                  } ${INTERACTION_FOCUS}`}
                >
                  {item.icon && (
                    <span
                      className={`inline-flex size-3.5 shrink-0 items-center justify-center ${
                        isDestructive ? "text-red-500" : "text-muted-foreground"
                      }`}
                    >
                      {item.icon}
                    </span>
                  )}
                  <span className="truncate flex-1">{item.label}</span>
                </button>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

export default SplitButton;

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

